                'address_hi' => '',
                'country_code' => '+91',
                'phone' => '040-67000000',
                'emergency_country_code' => '+91',
                'emergency_phone' => '040-67000000',
                'email' => 'bloodbank@continentalhospitals.com',
                'website' => 'https://continentalhospitals.com',
                'is_verified' => true,
                'is_24_7' => true,
                'is_government' => false,
                'component_facility' => true,
                'apheresis_facility' => true,
                'available_blood_groups' => [
                    'A+',
